\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\pagestyle{empty}

% ── Color Theme: Deep Navy + Amber/Coral (public exhibition) ──
\definecolor{primary}{HTML}{0F1F3D}      % deep navy
\definecolor{secondary}{HTML}{1A3A6B}    % medium navy
\definecolor{accent}{HTML}{E86A2B}       % warm coral/amber
\definecolor{accentgold}{HTML}{F5A623}   % bright amber
\definecolor{bgposter}{HTML}{0B1628}     % very dark navy bg
\definecolor{bgcard}{HTML}{152340}       % card bg (slightly lighter)
\definecolor{bglightcard}{HTML}{1C2E50}  % lighter card
\definecolor{bgstatcard}{HTML}{1F3560}   % stat callout bg
\definecolor{textlight}{HTML}{E8EDF5}    % main text on dark
\definecolor{textmuted}{HTML}{9DAFC8}    % muted text
\definecolor{textheader}{HTML}{FFFFFF}   % section header
\definecolor{accentlight}{HTML}{FF8C4A}  % lighter coral for highlights
\definecolor{goldlight}{HTML}{FFD080}    % light amber for numbers
\definecolor{successgreen}{HTML}{2ECC71} % green for positive stats
\definecolor{warnred}{HTML}{E74C3C}      % red for crisis stats
\definecolor{divider}{HTML}{2A4A7F}      % subtle divider

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=18pt, itemsep=5pt, parsep=0pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=5pt, parsep=0pt, topsep=2pt,
  label={\color{accentgold}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  navycard/.style={
    enhanced, arc=3pt, boxrule=0pt,
    colback=bgcard, colframe=divider, frame style={opacity=0.5},
    borderline west={4pt}{0pt}{accent},
    left=14pt, right=12pt, top=6pt, bottom=8pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{textheader},
    coltitle=textheader, colbacktitle=secondary,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top,
  },
  coralcard/.style={
    enhanced, arc=3pt, boxrule=0pt,
    colback=bglightcard, colframe=divider, frame style={opacity=0.5},
    borderline west={4pt}{0pt}{accentgold},
    left=14pt, right=12pt, top=6pt, bottom=8pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{textheader},
    coltitle=textheader, colbacktitle=bgcard,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top,
  },
  crisiscard/.style={
    enhanced, arc=3pt, boxrule=1.5pt,
    colback=bgcard, colframe=warnred, colframe=warnred,
    borderline west={5pt}{0pt}{warnred},
    left=14pt, right=12pt, top=6pt, bottom=8pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{textheader},
    coltitle=textheader, colbacktitle=warnred!70!bgcard,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top,
  },
  takeawaycard/.style={
    enhanced, arc=3pt, boxrule=0pt,
    colback=accent!25!bgcard,
    borderline west={5pt}{0pt}{accent},
    borderline north={2pt}{0pt}{accent!60},
    left=14pt, right=12pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=accent,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top,
  },
}

% ── Stat highlight box macro ──
\newcommand{\statbox}[4]{%
  % #1=number, #2=label, #3=number color, #4=box bg color
  \begin{tcolorbox}[
    enhanced, arc=4pt, boxrule=0pt,
    colback=#4, colframe=#3, frame style={opacity=0.3},
    left=8pt, right=8pt, top=6pt, bottom=6pt,
    halign=center, valign=center,
  ]
  {\fontsize{52}{60}\selectfont\bfseries\color{#3} #1}\\[2pt]
  {\fontsize{18}{22}\selectfont\color{textmuted} #2}
  \end{tcolorbox}%
}

% ── Year bar macro for historical chart ──
\newcommand{\yearbar}[3]{%
  % #1=label, #2=fill fraction (0-1), #3=color
  \noindent
  {\fontsize{18}{22}\selectfont\color{textmuted} #1}\hspace{6pt}%
  \begin{tikzpicture}[baseline=-2pt]
    \fill[divider] (0,0) rectangle (5.8cm, 0.32cm);
    \fill[#3] (0,0) rectangle (#2*5.8cm, 0.32cm);
  \end{tikzpicture}%
  \hspace{4pt}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

%% ══════════════════════════════════════════════════════
%% TITLE BAR — full width
%% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=primary, colframe=primary,
  left=28pt, right=28pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  borderline south={3pt}{0pt}{accent},
]{name=titlebar, column=1, span=2, between=top and row3}{
  {\fontsize{52}{62}\selectfont\bfseries\color{white}%
    The State of Global Education}\\[6pt]
  {\fontsize{28}{36}\selectfont\color{textmuted}%
    Progress, Gaps, and Inequality}\\[6pt]
  {\fontsize{17}{22}\selectfont\color{accent}%
    A data-driven look at two centuries of transformation — and the work still ahead}
}

%% ══════════════════════════════════════════════════════
%% STAT BANNER — 4 headline numbers, full width
%% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=bgstatcard,
  borderline south={2pt}{0pt}{divider},
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  halign=center, valign=center,
]{name=statbanner, column=1, span=2, between=row3 and row6}{
  \centering
  \begin{minipage}[c]{0.23\linewidth}
    \centering
    {\fontsize{46}{54}\selectfont\bfseries\color{successgreen} $>$4 in 5}\\[3pt]
    {\fontsize{16}{20}\selectfont\color{textmuted} Adults educated today}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.005\linewidth}
    \textcolor{divider}{\rule{1pt}{32mm}}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}
    \centering
    {\fontsize{46}{54}\selectfont\bfseries\color{warnred} 244M}\\[3pt]
    {\fontsize{16}{20}\selectfont\color{textmuted} Children out of school}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.005\linewidth}
    \textcolor{divider}{\rule{1pt}{32mm}}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}
    \centering
    {\fontsize{46}{54}\selectfont\bfseries\color{warnred} $<$20\%}\\[3pt]
    {\fontsize{16}{20}\selectfont\color{textmuted} Reach reading proficiency\\(low-income countries)}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.005\linewidth}
    \textcolor{divider}{\rule{1pt}{32mm}}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}
    \centering
    {\fontsize{46}{54}\selectfont\bfseries\color{accentgold} 3$\times$}\\[3pt]
    {\fontsize{16}{20}\selectfont\color{textmuted} Quality schooling gap:\\poorest vs. richest}
  \end{minipage}
}

%% ══════════════════════════════════════════════════════
%% LEFT COLUMN — rows 6-20
%% ══════════════════════════════════════════════════════

%% Section 1: Historical Progress
\posterbox[navycard, title={Two Centuries of Educational Expansion}
]{name=history, column=1, between=row6 and row11}{
  \fontsize{20}{28}\selectfont

  \noindent
  {\fontsize{19}{24}\selectfont\color{textmuted}\textit{%
    Education was once a privilege for a tiny elite. It is now a near-universal right.}}\\[8pt]

  % Visual bar chart of adult education rate
  \noindent
  \begin{tikzpicture}
    % 1800 bar
    \node[anchor=west, font=\fontsize{17}{20}\selectfont\color{textmuted}] at (0, 1.0) {1800};
    \fill[divider] (1.4cm, 0.76cm) rectangle (7.4cm, 1.22cm);
    \fill[accent!70] (1.4cm, 0.76cm) rectangle (2.58cm, 1.22cm); % ~20%
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{accent!90}] at (7.55cm, 0.99cm) {$<$20\%};
    % 2024 bar
    \node[anchor=west, font=\fontsize{17}{20}\selectfont\color{textmuted}] at (0, 0.1) {2024};
    \fill[divider] (1.4cm, -0.14cm) rectangle (7.4cm, 0.32cm);
    \fill[successgreen!80] (1.4cm, -0.14cm) rectangle (7.24cm, 0.32cm); % ~84%
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{successgreen}] at (7.55cm, 0.09cm) {$>$80\%};
    % label
    \node[anchor=west, font=\fontsize{14}{18}\selectfont\color{textmuted}] at (1.4cm, -0.45cm) {Share of adults with formal education};
  \end{tikzpicture}\\[10pt]

  \begin{itemize}
    \item Fewer than \textbf{\color{accent}1 in 5} adults educated in 1800
    \item More than \textbf{\color{successgreen}4 in 5} adults educated today
    \item Literacy rates mirror this transformation globally
    \item A 200-year arc from elite privilege $\to$ near-universal access
  \end{itemize}\\[4pt]

  \noindent
  \colorbox{accent!20!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{18}{24}\selectfont\color{textlight}
    \textbf{\color{accentgold} The single greatest expansion} of human opportunity in recorded history — but the story doesn't end here.
  }}
}

%% Section 3: Out-of-school children
\posterbox[crisiscard, title={244 Million Children Still Out of School}
]{name=outofschool, column=1, between=row11 and row17}{
  \fontsize{20}{28}\selectfont

  \noindent
  \begin{center}
    {\fontsize{80}{90}\selectfont\bfseries\color{warnred} 244}\\[-4pt]
    {\fontsize{22}{28}\selectfont\bfseries\color{textmuted} million children not in school (2023)}
  \end{center}\\[4pt]

  % Breakdown visual
  \noindent
  \colorbox{warnred!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{18}{24}\selectfont
    \begin{tabular}{@{}lll@{}}
      \textbf{\color{warnred} $\sim$60M} & {\color{textmuted} primary-school age} & {\color{textmuted}(6--11 yrs)}\\[4pt]
      \textbf{\color{warnred} $\sim$184M} & {\color{textmuted} secondary-school age} & {\color{textmuted}(12--17 yrs)}\\
    \end{tabular}
  }}\\[8pt]

  \begin{itemize}
    \item \textbf{Secondary dropout is the dominant driver}
    \item Many complete primary school but never continue
    \item Concentrated in Sub-Saharan Africa \& South Asia
    \item Conflict, poverty, and distance are key barriers
  \end{itemize}\\[6pt]

  \noindent
  \colorbox{warnred!20!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{18}{24}\selectfont\color{textlight}
    \centering
    This number is \textbf{\color{warnred} larger than the entire population of Brazil}.
  }}
}

%% Section 5: Gender Gap
\posterbox[coralcard, title={Closing the Gender Gap}
]{name=gender, column=1, between=row17 and bottom}{
  \fontsize{19}{26}\selectfont

  \noindent
  {\fontsize{18}{23}\selectfont\color{textmuted}\textit{%
    Historically, boys were far more likely to attend school than girls.}}\\[6pt]

  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{@{}p{3.4cm}p{5.8cm}@{}}
    \rowcolor{bgcard}
    {\fontsize{16}{20}\selectfont\color{textmuted}\textbf{Level}} &
    {\fontsize{16}{20}\selectfont\color{textmuted}\textbf{Gender Gap (2023)}} \\
    \rowcolor{bglightcard}
    {\fontsize{17}{22}\selectfont Primary} &
    {\fontsize{17}{22}\selectfont\color{successgreen} Nearly closed globally} \\
    \rowcolor{bgcard}
    {\fontsize{17}{22}\selectfont Secondary} &
    {\fontsize{17}{22}\selectfont\color{successgreen} Nearly closed globally} \\
    \rowcolor{bglightcard}
    {\fontsize{17}{22}\selectfont Tertiary} &
    {\fontsize{17}{22}\selectfont\color{accentgold} Women now exceed men} \\
  \end{tabular}\\[6pt]

  \noindent
  \colorbox{warnred!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{22}\selectfont
    \textbf{\color{warnred} Exception:} In Afghanistan and some other nations, girls remain severely excluded at all levels.
  }}
}

%% ══════════════════════════════════════════════════════
%% RIGHT COLUMN — rows 6-20
%% ══════════════════════════════════════════════════════

%% Section 2: Learning Crisis
\posterbox[crisiscard, title={The Learning Crisis: Enrollment $\neq$ Learning}
]{name=crisis, column=2, between=row6 and row12}{
  \fontsize{20}{28}\selectfont

  \noindent
  {\fontsize{19}{24}\selectfont\color{textmuted}\textit{%
    Being in school is not the same as learning. Millions attend without gaining basic skills.}}\\[8pt]

  \noindent
  \begin{center}
    \begin{tikzpicture}
      % Large donut-style visual: only 20% proficient
      % Background circle (full)
      \fill[divider] (0,0) circle (2.5cm);
      % Arc for proficient: 20% = 72 degrees
      \fill[successgreen!80] (0,0) -- (2.5cm, 0) arc(0:72:2.5cm) -- cycle;
      % White inner circle (donut hole)
      \fill[bgcard] (0,0) circle (1.45cm);
      % Center label
      \node[font=\fontsize{30}{36}\selectfont\bfseries, text=warnred] at (0,0.15) {$<$20\%};
      \node[font=\fontsize{13}{16}\selectfont, text=textmuted] at (0,-0.4) {proficient};
      % Outer label
      \node[font=\fontsize{14}{17}\selectfont, text=textmuted, anchor=west] at (2.7cm, 0.8cm) {Reach minimum};
      \node[font=\fontsize{14}{17}\selectfont, text=textmuted, anchor=west] at (2.7cm, 0.4cm) {reading proficiency};
      \node[font=\fontsize{14}{17}\selectfont, text=successgreen, anchor=west] at (2.7cm,-0.15cm) {(low-income)};
      \node[font=\fontsize{14}{17}\selectfont, text=textmuted, anchor=west] at (2.7cm,-0.6cm) {by end of};
      \node[font=\fontsize{14}{17}\selectfont, text=textmuted, anchor=west] at (2.7cm,-1.0cm) {primary school};
      % The 80% sector label
      \node[font=\fontsize{14}{17}\selectfont, text=warnred!80, anchor=east] at (-2.7cm, -0.4cm) {80\%+ enrolled};
      \node[font=\fontsize{14}{17}\selectfont, text=warnred!80, anchor=east] at (-2.7cm, -0.8cm) {but not learning};
    \end{tikzpicture}
  \end{center}\\[4pt]

  \begin{itemize}
    \item Enrollment ≠ proficiency: the gap is stark
    \item Most children cannot \textbf{identify key ideas} in a text
    \item Invisible crisis: hidden behind positive enrollment data
    \item Problem concentrated in \textbf{lower-income countries}
  \end{itemize}
}

%% Section 4: Quality Schooling Inequality
\posterbox[coralcard, title={A World Divided: Quality Schooling}
]{name=quality, column=2, between=row12 and row18}{
  \fontsize{20}{28}\selectfont

  \noindent
  {\fontsize{18}{23}\selectfont\color{textmuted}\textit{%
    Same years enrolled, vastly different years \textbf{actually learned}.}}\\[8pt]

  % Visual bar comparison
  \noindent
  \begin{tikzpicture}
    % Title row
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\color{textmuted}] at (0, 4.2) {Learning-Adjusted Years of Schooling};

    % Bar 1: Poorest < 3 years
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 3.5) {Poorest countries};
    \fill[divider] (4.6cm, 3.2cm) rectangle (10.8cm, 3.75cm);
    \fill[warnred] (4.6cm, 3.2cm) rectangle (6.25cm, 3.75cm); % 3/11 * full
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{warnred}] at (10.95cm, 3.47cm) {$<$3 yrs};

    % Bar 2: South Asia / SSA < 7 years
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 2.55) {South Asia / Sub-Saharan Africa};
    \fill[divider] (4.6cm, 2.25cm) rectangle (10.8cm, 2.80cm);
    \fill[accentgold!70] (4.6cm, 2.25cm) rectangle (8.35cm, 2.80cm); % 7/11
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{accentgold}] at (10.95cm, 2.52cm) {$<$7 yrs};

    % Bar 3: High-income 10+
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 1.6) {High-income countries};
    \fill[divider] (4.6cm, 1.3cm) rectangle (10.8cm, 1.85cm);
    \fill[successgreen!80] (4.6cm, 1.3cm) rectangle (10.6cm, 1.85cm); % 10+/11
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{successgreen}] at (10.95cm, 1.57cm) {10+ yrs};

    % Scale ticks
    \foreach \x/\label in {4.6/0, 6.25/3, 7.82/6, 9.38/9, 10.8/11} {
      \draw[textmuted, opacity=0.4] (\x cm, 0.9cm) -- (\x cm, 1.1cm);
      \node[font=\fontsize{12}{15}\selectfont\color{textmuted}, opacity=0.7] at (\x cm, 0.65cm) {\label};
    }
    \node[font=\fontsize{13}{16}\selectfont\color{textmuted}] at (7.7cm, 0.3cm) {Years};
  \end{tikzpicture}\\[6pt]

  \begin{itemize}
    \item Children in poorest nations get \textbf{less than $\frac{1}{3}$} the quality schooling of wealthy peers
    \item Most of world's children live where averages are \textbf{below 7 years}
    \item Gap reflects \textbf{teacher quality, resources}, and school infrastructure
  \end{itemize}\\[4pt]

  \noindent
  \colorbox{accentgold!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{22}\selectfont
    \centering
    A child born in a poor country faces a \textbf{\color{warnred} 3× disadvantage} in quality education before they turn 15.
  }}
}

%% Takeaway / Key Message
\posterbox[takeawaycard, title={Key Takeaway}
]{name=takeaway, column=2, between=row18 and bottom}{
  \fontsize{20}{28}\selectfont

  \begin{itemize}[label={\color{white}$\star$}]
    \item Remarkable progress over 200 years — but \textbf{hundreds of millions} left behind
    \item 244 million children out of school; many more \textbf{learning too little}
    \item \textbf{Closing the learning gap} — not just enrollment — is the defining challenge
