    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 1.6) {High-income countries};
    \fill[divider] (4.6cm, 1.3cm) rectangle (10.8cm, 1.85cm);
    \fill[successgreen!80] (4.6cm, 1.3cm) rectangle (10.6cm, 1.85cm); % 10+/11
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{successgreen}] at (10.95cm, 1.57cm) {10+ yrs};

