      \node[font=\fontsize{12}{15}\selectfont\color{textmuted}, opacity=0.7] at (\x cm, 0.65cm) {\label};
    }
    \node[font=\fontsize{13}{16}\selectfont\color{textmuted}] at (7.7cm, 0.3cm) {Years};
  \end{tikzpicture}\\[6pt]

  \begin{itemize}
    \item Children in poorest nations get \textbf{less than $\frac{1}{3}$} the quality schooling of wealthy peers
    \item Most of world's children live where averages are \textbf{below 7 years}
    \item Gap reflects \textbf{teacher quality, resources}, and school infrastructure
  \end{itemize}\\[4pt]

  \noindent
  \colorbox{accentgold!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{22}\selectfont
    \centering
    A child born in a poor country faces a \textbf{\color{warnred} 3× disadvantage} in quality education before they turn 15.
  }}
}

