\posterbox[takeawaycard, title={Key Takeaway}
]{name=takeaway, column=2, between=row18 and bottom}{
  \fontsize{20}{28}\selectfont

  \begin{itemize}[label={\color{white}$\star$}]
    \item Remarkable progress over 200 years — but \textbf{hundreds of millions} left behind
    \item 244 million children out of school; many more \textbf{learning too little}
    \item \textbf{Closing the learning gap} — not just enrollment — is the defining challenge
    \item \textbf{Geography and income} still determine educational fate
  \end{itemize}\\[6pt]

