%% Section 2: Learning Crisis
\posterbox[crisiscard, title={The Learning Crisis: Enrollment $\neq$ Learning}
]{name=crisis, column=2, between=row6 and row12}{
  \fontsize{20}{28}\selectfont

  \noindent
  {\fontsize{19}{24}\selectfont\color{textmuted}\textit{%
    Being in school is not the same as learning. Millions attend without gaining basic skills.}}\\[8pt]

  \noindent
  \begin{center}
    \begin{tikzpicture}
      % Large donut-style visual: only 20% proficient
      % Background circle (full)
      \fill[divider] (0,0) circle (2.5cm);
      % Arc for proficient: 20% = 72 degrees
      \fill[successgreen!80] (0,0) -- (2.5cm, 0) arc(0:72:2.5cm) -- cycle;
      % White inner circle (donut hole)
      \fill[bgcard] (0,0) circle (1.45cm);
      % Center label
      \node[font=\fontsize{30}{36}\selectfont\bfseries, text=warnred] at (0,0.15) {$<$20\%};
      \node[font=\fontsize{13}{16}\selectfont, text=textmuted] at (0,-0.4) {proficient};
      % Outer label
      \node[font=\fontsize{14}{17}\selectfont, text=textmuted, anchor=west] at (2.7cm, 0.8cm) {Reach minimum};
      \node[font=\fontsize{14}{17}\selectfont, text=textmuted, anchor=west] at (2.7cm, 0.4cm) {reading proficiency};
      \node[font=\fontsize{14}{17}\selectfont, text=successgreen, anchor=west] at (2.7cm,-0.15cm) {(low-income)};
      \node[font=\fontsize{14}{17}\selectfont, text=textmuted, anchor=west] at (2.7cm,-0.6cm) {by end of};
      \node[font=\fontsize{14}{17}\selectfont, text=textmuted, anchor=west] at (2.7cm,-1.0cm) {primary school};
      % The 80% sector label
      \node[font=\fontsize{14}{17}\selectfont, text=warnred!80, anchor=east] at (-2.7cm, -0.4cm) {80\%+ enrolled};
      \node[font=\fontsize{14}{17}\selectfont, text=warnred!80, anchor=east] at (-2.7cm, -0.8cm) {but not learning};
    \end{tikzpicture}
  \end{center}\\[4pt]

  \begin{itemize}
    \item Enrollment ≠ proficiency: the gap is stark
    \item Most children cannot \textbf{identify key ideas} in a text
    \item Invisible crisis: hidden behind positive enrollment data
    \item Problem concentrated in \textbf{lower-income countries}
  \end{itemize}
}

%% Section 4: Quality Schooling Inequality
\posterbox[coralcard, title={A World Divided: Quality Schooling}
]{name=quality, column=2, between=row12 and row18}{
  \fontsize{20}{28}\selectfont

  \noindent
  {\fontsize{18}{23}\selectfont\color{textmuted}\textit{%
    Same years enrolled, vastly different years \textbf{actually learned}.}}\\[8pt]

  % Visual bar comparison
  \noindent
  \begin{tikzpicture}
    % Title row
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\color{textmuted}] at (0, 4.2) {Learning-Adjusted Years of Schooling};

    % Bar 1: Poorest < 3 years
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 3.5) {Poorest countries};
    \fill[divider] (4.6cm, 3.2cm) rectangle (10.8cm, 3.75cm);
    \fill[warnred] (4.6cm, 3.2cm) rectangle (6.25cm, 3.75cm); % 3/11 * full
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{warnred}] at (10.95cm, 3.47cm) {$<$3 yrs};

    % Bar 2: South Asia / SSA < 7 years
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 2.55) {South Asia / Sub-Saharan Africa};
    \fill[divider] (4.6cm, 2.25cm) rectangle (10.8cm, 2.80cm);
    \fill[accentgold!70] (4.6cm, 2.25cm) rectangle (8.35cm, 2.80cm); % 7/11
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{accentgold}] at (10.95cm, 2.52cm) {$<$7 yrs};

    % Bar 3: High-income 10+
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 1.6) {High-income countries};
    \fill[divider] (4.6cm, 1.3cm) rectangle (10.8cm, 1.85cm);
    \fill[successgreen!80] (4.6cm, 1.3cm) rectangle (10.6cm, 1.85cm); % 10+/11
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\bfseries\color{successgreen}] at (10.95cm, 1.57cm) {10+ yrs};

    % Scale ticks
    \foreach \x/\label in {4.6/0, 6.25/3, 7.82/6, 9.38/9, 10.8/11} {
      \draw[textmuted, opacity=0.4] (\x cm, 0.9cm) -- (\x cm, 1.1cm);
      \node[font=\fontsize{12}{15}\selectfont\color{textmuted}, opacity=0.7] at (\x cm, 0.65cm) {\label};
    }
    \node[font=\fontsize{13}{16}\selectfont\color{textmuted}] at (7.7cm, 0.3cm) {Years};
  \end{tikzpicture}\\[6pt]

  \begin{itemize}
    \item Children in poorest nations get \textbf{less than $\frac{1}{3}$} the quality schooling of wealthy peers
    \item Most of world's children live where averages are \textbf{below 7 years}
    \item Gap reflects \textbf{teacher quality, resources}, and school infrastructure
  \end{itemize}\\[4pt]

  \noindent
  \colorbox{accentgold!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{22}\selectfont
    \centering
    A child born in a poor country faces a \textbf{\color{warnred} 3× disadvantage} in quality education before they turn 15.
  }}
}

%% Takeaway / Key Message
\posterbox[takeawaycard, title={Key Takeaway}
]{name=takeaway, column=2, between=row18 and bottom}{
  \fontsize{20}{28}\selectfont

  \begin{itemize}[label={\color{white}$\star$}]
    \item Remarkable progress over 200 years — but \textbf{hundreds of millions} left behind
    \item 244 million children out of school; many more \textbf{learning too little}
    \item \textbf{Closing the learning gap} — not just enrollment — is the defining challenge
    \item \textbf{Geography and income} still determine educational fate
  \end{itemize}\\[6pt]

  \noindent
  \colorbox{primary!60!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{22}\selectfont\color{textlight}\centering
    \textit{``The job is not done until every child has access to \textbf{quality} education — not just a seat in a classroom.''}
  }}
}

