  navycard/.style={
    enhanced, arc=3pt, boxrule=0pt,
    colback=bgcard, colframe=divider, frame style={opacity=0.5},
    borderline west={4pt}{0pt}{accent},
    left=14pt, right=12pt, top=6pt, bottom=8pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{textheader},
    coltitle=textheader, colbacktitle=secondary,

