\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{helvet}
\renewcommand{\familydefault}{\sfdefault}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\pagestyle{empty}

% ── Color Theme: Deep Navy + Amber/Coral (public exhibition) ──
\definecolor{primary}{HTML}{0D1B35}      % deep navy
\definecolor{secondary}{HTML}{1A3A6B}    % medium navy
\definecolor{accent}{HTML}{E86A2B}       % warm coral/amber
\definecolor{accentgold}{HTML}{F5A623}   % bright amber
\definecolor{bgposter}{HTML}{0A1526}     % very dark navy bg
\definecolor{bgcard}{HTML}{142035}       % card bg (slightly lighter)
\definecolor{bglightcard}{HTML}{1C2E50}  % lighter card
\definecolor{bgstatcard}{HTML}{1A3060}   % stat callout bg
\definecolor{textlight}{HTML}{E8EDF5}    % main text on dark
\definecolor{textmuted}{HTML}{9DAFC8}    % muted text
\definecolor{textheader}{HTML}{FFFFFF}   % section header
\definecolor{successgreen}{HTML}{27AE60} % green for positive stats
\definecolor{warnred}{HTML}{E74C3C}      % red for crisis stats
\definecolor{divider}{HTML}{2A4A7F}      % subtle divider

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=18pt, itemsep=4pt, parsep=0pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}

% ── Card styles ──
\tcbset{
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=bgcard,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=secondary,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top,
  },
  coralcard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=bglightcard,
    borderline west={5pt}{0pt}{accentgold},
    left=14pt, right=12pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=bgcard,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top,
  },
  crisiscard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=bgcard,
    borderline west={5pt}{0pt}{warnred},
    left=14pt, right=12pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=warnred!60!bgcard,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top,
  },
  takeawaycard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=accent!20!bgcard,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{26}{32}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=accent,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=0pt,
    valign=top,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

%% ══════════════════════════════════════════════════════
%% TITLE BAR
%% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=primary, colframe=primary,
  left=30pt, right=30pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
  borderline south={3pt}{0pt}{accent},
]{name=titlebar, column=1, span=2, between=top and row3}{
  {\fontsize{54}{64}\selectfont\bfseries\color{white}
    The State of Global Education}\\[8pt]
  {\fontsize{28}{36}\selectfont\color{textmuted}
    Progress, Gaps, and Inequality}\\[6pt]
  {\fontsize{18}{24}\selectfont\color{accent}
    A data-driven look at two centuries of transformation --- and the work still ahead}
}

%% ══════════════════════════════════════════════════════
%% STAT BANNER
%% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=bgstatcard,
  borderline south={2pt}{0pt}{divider},
  left=8pt, right=8pt, top=8pt, bottom=8pt,
  halign=center, valign=center,
]{name=statbanner, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.22\linewidth}
    \centering
    {\fontsize{44}{52}\selectfont\bfseries\color{successgreen} $>$4 in 5}\\[3pt]
    {\fontsize{16}{20}\selectfont\color{textmuted} Adults with formal\\education today}
  \end{minipage}\hfill
  \textcolor{divider}{\rule{1.5pt}{30mm}}\hfill
  \begin{minipage}[c]{0.22\linewidth}
    \centering
    {\fontsize{44}{52}\selectfont\bfseries\color{warnred} 244M}\\[3pt]
    {\fontsize{16}{20}\selectfont\color{textmuted} Children out of\\school (2023)}
  \end{minipage}\hfill
  \textcolor{divider}{\rule{1.5pt}{30mm}}\hfill
  \begin{minipage}[c]{0.22\linewidth}
    \centering
    {\fontsize{44}{52}\selectfont\bfseries\color{warnred} $<$20\%}\\[3pt]
    {\fontsize{16}{20}\selectfont\color{textmuted} Reading proficiency\\(low-income countries)}
  \end{minipage}\hfill
  \textcolor{divider}{\rule{1.5pt}{30mm}}\hfill
  \begin{minipage}[c]{0.22\linewidth}
    \centering
    {\fontsize{44}{52}\selectfont\bfseries\color{accentgold} 3$\times$}\\[3pt]
    {\fontsize{16}{20}\selectfont\color{textmuted} Quality schooling gap:\\poorest vs.\ richest}
  \end{minipage}
}

%% ══════════════════════════════════════════════════════
%% LEFT COLUMN
%% ══════════════════════════════════════════════════════

\posterbox[navycard, title={Two Centuries of Educational Expansion}
]{name=history, column=1, between=row5 and row10}{
  \fontsize{19}{27}\selectfont
  {\fontsize{17}{22}\selectfont\color{textmuted}\textit{%
    Education was once a privilege for the elite.
    It is now a near-universal right.}}

  \vspace{8pt}
  \noindent\begin{tikzpicture}
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 0.9) {1800};
    \fill[divider] (1.3cm, 0.64cm) rectangle (7.2cm, 1.10cm);
    \fill[accent!80] (1.3cm, 0.64cm) rectangle (2.48cm, 1.10cm);
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{accent}] at (7.32cm, 0.87cm) {$<$20\%};
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 0.05) {2024};
    \fill[divider] (1.3cm, -0.18cm) rectangle (7.2cm, 0.28cm);
    \fill[successgreen!85] (1.3cm, -0.18cm) rectangle (7.08cm, 0.28cm);
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{successgreen}] at (7.32cm, 0.05cm) {$>$80\%};
    \node[anchor=west, font=\fontsize{13}{17}\selectfont\color{textmuted}] at (1.3cm, -0.5cm) {Share of adults with formal education};
  \end{tikzpicture}

  \vspace{8pt}
  \begin{itemize}
    \item Fewer than \textbf{\color{accent}1 in 5} adults educated in 1800
    \item More than \textbf{\color{successgreen}4 in 5} adults educated today
    \item Literacy rates have followed the same trajectory
    \item 200 years: elite privilege $\to$ near-universal access
  \end{itemize}

  \vspace{6pt}
  \noindent\colorbox{accent!22!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{22}\selectfont\color{textlight}
    \textbf{\color{accentgold} The single greatest expansion} of human
    opportunity in recorded history --- but the story is not over.
  }}
}

\posterbox[crisiscard, title={244 Million Children Still Out of School}
]{name=outofschool, column=1, between=row10 and row16}{
  \fontsize{19}{27}\selectfont

  \begin{center}
    {\fontsize{90}{100}\selectfont\bfseries\color{warnred} 244}\\[2pt]
    {\fontsize{21}{27}\selectfont\bfseries\color{textmuted} million children not in school (2023)}
  \end{center}

  \vspace{6pt}
  \noindent\colorbox{warnred!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{23}\selectfont
    \begin{tabular}{@{}lll@{}}
      \textbf{\color{warnred} $\sim$60M} & {\color{textmuted} primary-school age} & {\color{textmuted}(6--11 yrs)}\\[4pt]
      \textbf{\color{warnred} $\sim$184M} & {\color{textmuted} secondary-school age} & {\color{textmuted}(12--17 yrs)}\\
    \end{tabular}
  }}

  \vspace{8pt}
  \begin{itemize}
    \item \textbf{Secondary dropout is the dominant driver}
    \item Many finish primary --- but never continue
    \item Concentrated in Sub-Saharan Africa \& South Asia
    \item Conflict, poverty, and distance are key barriers
  \end{itemize}

  \vspace{6pt}
  \noindent\colorbox{warnred!20!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{22}\selectfont\color{textlight}\centering
    \textbf{Larger than the entire population of Brazil.}
  }}
}

\posterbox[coralcard, title={Closing the Gender Gap}
]{name=gender, column=1, between=row16 and bottom}{
  \fontsize{18}{25}\selectfont
  {\fontsize{16}{21}\selectfont\color{textmuted}\textit{%
    Historically, boys were far more likely to attend school.}}

  \vspace{8pt}
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{@{}p{3.2cm}p{5.6cm}@{}}
    \rowcolor{bgcard}
    {\fontsize{15}{19}\selectfont\color{textmuted}\textbf{Level}} &
    {\fontsize{15}{19}\selectfont\color{textmuted}\textbf{Gender Gap (2023)}} \\
    \rowcolor{bglightcard}
    {\fontsize{16}{21}\selectfont Primary} &
    {\fontsize{16}{21}\selectfont\color{successgreen} Nearly closed globally} \\
    \rowcolor{bgcard}
    {\fontsize{16}{21}\selectfont Secondary} &
    {\fontsize{16}{21}\selectfont\color{successgreen} Nearly closed globally} \\
    \rowcolor{bglightcard}
    {\fontsize{16}{21}\selectfont Tertiary} &
    {\fontsize{16}{21}\selectfont\color{accentgold} Women now exceed men} \\
  \end{tabular}

  \vspace{6pt}
  \noindent\colorbox{warnred!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{16}{21}\selectfont
    \textbf{\color{warnred} Exception:} In Afghanistan and parts of the
    Sahel, girls remain severely excluded at all levels.
  }}
}

%% ══════════════════════════════════════════════════════
%% RIGHT COLUMN
%% ══════════════════════════════════════════════════════

\posterbox[crisiscard, title={The Learning Crisis: Enrollment $\neq$ Learning}
]{name=crisis, column=2, between=row5 and row11}{
  \fontsize{19}{27}\selectfont
  {\fontsize{17}{22}\selectfont\color{textmuted}\textit{%
    Being in school is not the same as learning. Millions attend
    without gaining basic skills.}}

  \vspace{8pt}
  \begin{center}
    \begin{tikzpicture}
      % Donut chart: only 20% proficient
      \fill[divider] (0,0) circle (2.4cm);
      \fill[successgreen!75] (0,0) -- (2.4cm, 0) arc(0:72:2.4cm) -- cycle;
      \fill[bgcard] (0,0) circle (1.38cm);
      \node[font=\fontsize{28}{34}\selectfont\bfseries, text=warnred] at (0,0.14) {$<$20\%};
      \node[font=\fontsize{12}{15}\selectfont, text=textmuted] at (0,-0.36) {proficient};
      \node[font=\fontsize{13}{16}\selectfont, text=textmuted, anchor=west] at (2.55cm, 0.75cm) {Reach minimum};
      \node[font=\fontsize{13}{16}\selectfont, text=textmuted, anchor=west] at (2.55cm, 0.37cm) {reading proficiency};
      \node[font=\fontsize{13}{16}\selectfont, text=successgreen, anchor=west] at (2.55cm,-0.08cm) {(low-income)};
      \node[font=\fontsize{13}{16}\selectfont, text=textmuted, anchor=west] at (2.55cm,-0.45cm) {by end of primary};
      \node[font=\fontsize{13}{16}\selectfont, text=warnred!80, anchor=east] at (-2.55cm, -0.5cm) {80\%+ enrolled};
      \node[font=\fontsize{13}{16}\selectfont, text=warnred!80, anchor=east] at (-2.55cm, -0.88cm) {but not learning};
    \end{tikzpicture}
  \end{center}

  \vspace{6pt}
  \begin{itemize}
    \item Enrollment $\neq$ proficiency: the gap is stark
    \item Most cannot \textbf{identify key ideas} in a text
    \item Invisible crisis: hidden behind enrollment data
    \item Problem concentrated in \textbf{lower-income countries}
  \end{itemize}
}

\posterbox[coralcard, title={A World Divided: Quality Schooling}
]{name=quality, column=2, between=row11 and row17}{
  \fontsize{19}{27}\selectfont
  {\fontsize{17}{22}\selectfont\color{textmuted}\textit{%
    Same years enrolled, vastly different years \textbf{actually learned.}}}

  \vspace{8pt}
  \begin{tikzpicture}
    \node[anchor=west, font=\fontsize{14}{18}\selectfont\color{textmuted}]
      at (0, 4.1) {Learning-Adjusted Years of Schooling};

    % Bar 1: Poorest <3 years
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\color{textmuted}]
      at (0, 3.45) {Poorest countries};
    \fill[divider] (4.4cm, 3.15cm) rectangle (10.6cm, 3.70cm);
    \fill[warnred] (4.4cm, 3.15cm) rectangle (6.09cm, 3.70cm);
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{warnred}]
      at (10.75cm, 3.42cm) {$<$3 yrs};

    % Bar 2: SSA/SA <7 years
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\color{textmuted}]
      at (0, 2.52) {South Asia / Sub-Saharan Africa};
    \fill[divider] (4.4cm, 2.22cm) rectangle (10.6cm, 2.77cm);
    \fill[accentgold!75] (4.4cm, 2.22cm) rectangle (8.32cm, 2.77cm);
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{accentgold}]
      at (10.75cm, 2.49cm) {$<$7 yrs};

    % Bar 3: High-income 10+
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\color{textmuted}]
      at (0, 1.58) {High-income countries};
    \fill[divider] (4.4cm, 1.28cm) rectangle (10.6cm, 1.83cm);
    \fill[successgreen!80] (4.4cm, 1.28cm) rectangle (10.4cm, 1.83cm);
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{successgreen}]
      at (10.75cm, 1.55cm) {10+ yrs};

    % Scale ticks
    \foreach \x/\lab in {4.4/0, 6.09/3, 7.79/7, 10.4/10} {
      \draw[textmuted, opacity=0.4] (\x cm, 0.90cm) -- (\x cm, 1.05cm);
      \node[font=\fontsize{11}{14}\selectfont\color{textmuted}, opacity=0.7]
        at (\x cm, 0.65cm) {\lab};
    }
    \node[font=\fontsize{12}{15}\selectfont\color{textmuted}]
      at (7.5cm, 0.30cm) {Years};
  \end{tikzpicture}

  \vspace{6pt}
  \begin{itemize}
    \item Children in poorest nations get \textbf{less than $\frac{1}{3}$} the quality schooling of wealthy peers
    \item Most of the world's children live where averages fall \textbf{below 7 years}
    \item Gap reflects teacher quality, resources, and infrastructure
  \end{itemize}

  \vspace{4pt}
  \noindent\colorbox{accentgold!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{16}{21}\selectfont\centering
    A child born poor faces a \textbf{\color{warnred} 3$\times$ disadvantage}
    in quality education before turning 15.
  }}
}

\posterbox[takeawaycard, title={Key Takeaway}
]{name=takeaway, column=2, between=row17 and bottom}{
  \fontsize{19}{27}\selectfont

  \begin{itemize}[label={\color{white}$\star$}]
    \item Remarkable progress over 200 years --- but \textbf{hundreds of millions} left behind
    \item 244 million children out of school; many more \textbf{learning too little}
    \item \textbf{Closing the learning gap} --- not just enrollment --- is the defining challenge
    \item \textbf{Geography and income} still determine a child's educational fate
  \end{itemize}

  \vspace{6pt}
  \noindent\colorbox{primary!60!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{16}{21}\selectfont\color{textlight}\centering
    \textit{``The job is not done until every child has access to
    \textbf{quality} education --- not just a seat in a classroom.''}
  }}
}

