\posterbox[navycard, title={Two Centuries of Educational Expansion}
]{name=history, column=1, between=row5 and row10}{
  \fontsize{19}{27}\selectfont
  {\fontsize{17}{22}\selectfont\color{textmuted}\textit{%
    Education was once a privilege for the elite.
    It is now a near-universal right.}}

  \vspace{8pt}
  \noindent\begin{tikzpicture}
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 0.9) {1800};
    \fill[divider] (1.3cm, 0.64cm) rectangle (7.2cm, 1.10cm);
    \fill[accent!80] (1.3cm, 0.64cm) rectangle (2.48cm, 1.10cm);
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{accent}] at (7.32cm, 0.87cm) {$<$20\%};
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 0.05) {2024};
    \fill[divider] (1.3cm, -0.18cm) rectangle (7.2cm, 0.28cm);
    \fill[successgreen!85] (1.3cm, -0.18cm) rectangle (7.08cm, 0.28cm);
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{successgreen}] at (7.32cm, 0.05cm) {$>$80\%};
    \node[anchor=west, font=\fontsize{13}{17}\selectfont\color{textmuted}] at (1.3cm, -0.5cm) {Share of adults with formal education};
  \end{tikzpicture}

  \vspace{8pt}
  \begin{itemize}
    \item Fewer than \textbf{\color{accent}1 in 5} adults educated in 1800
    \item More than \textbf{\color{successgreen}4 in 5} adults educated today
    \item Literacy rates have followed the same trajectory
    \item 200 years: elite privilege $\to$ near-universal access
  \end{itemize}

  \vspace{6pt}
  \noindent\colorbox{accent!22!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{22}\selectfont\color{textlight}
    \textbf{\color{accentgold} The single greatest expansion} of human
    opportunity in recorded history --- but the story is not over.
  }}
}

\posterbox[crisiscard, title={244 Million Children Still Out of School}
]{name=outofschool, column=1, between=row10 and row16}{
  \fontsize{19}{27}\selectfont

  \begin{center}
    {\fontsize{90}{100}\selectfont\bfseries\color{warnred} 244}\\[2pt]
    {\fontsize{21}{27}\selectfont\bfseries\color{textmuted} million children not in school (2023)}
  \end{center}

  \vspace{6pt}
  \noindent\colorbox{warnred!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{23}\selectfont
    \begin{tabular}{@{}lll@{}}
      \textbf{\color{warnred} $\sim$60M} & {\color{textmuted} primary-school age} & {\color{textmuted}(6--11 yrs)}\\[4pt]
      \textbf{\color{warnred} $\sim$184M} & {\color{textmuted} secondary-school age} & {\color{textmuted}(12--17 yrs)}\\
    \end{tabular}
  }}

  \vspace{8pt}
  \begin{itemize}
    \item \textbf{Secondary dropout is the dominant driver}
    \item Many finish primary --- but never continue
    \item Concentrated in Sub-Saharan Africa \& South Asia
    \item Conflict, poverty, and distance are key barriers
  \end{itemize}

  \vspace{6pt}
  \noindent\colorbox{warnred!20!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{22}\selectfont\color{textlight}\centering
    \textbf{Larger than the entire population of Brazil.}
  }}
}

\posterbox[coralcard, title={Closing the Gender Gap}
]{name=gender, column=1, between=row16 and bottom}{
  \fontsize{18}{25}\selectfont
  {\fontsize{16}{21}\selectfont\color{textmuted}\textit{%
    Historically, boys were far more likely to attend school.}}

  \vspace{8pt}
  \renewcommand{\arraystretch}{1.5}
  \begin{tabular}{@{}p{3.2cm}p{5.6cm}@{}}
    \rowcolor{bgcard}
    {\fontsize{15}{19}\selectfont\color{textmuted}\textbf{Level}} &
    {\fontsize{15}{19}\selectfont\color{textmuted}\textbf{Gender Gap (2023)}} \\
    \rowcolor{bglightcard}
    {\fontsize{16}{21}\selectfont Primary} &
    {\fontsize{16}{21}\selectfont\color{successgreen} Nearly closed globally} \\
    \rowcolor{bgcard}
    {\fontsize{16}{21}\selectfont Secondary} &
    {\fontsize{16}{21}\selectfont\color{successgreen} Nearly closed globally} \\
    \rowcolor{bglightcard}
    {\fontsize{16}{21}\selectfont Tertiary} &
    {\fontsize{16}{21}\selectfont\color{accentgold} Women now exceed men} \\
  \end{tabular}

  \vspace{6pt}
  \noindent\colorbox{warnred!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{16}{21}\selectfont
    \textbf{\color{warnred} Exception:} In Afghanistan and parts of the
    Sahel, girls remain severely excluded at all levels.
  }}
}

