151	\posterbox[navycard, title={Two Centuries of Educational Expansion}
152	]{name=history, column=1, between=row4 and row10}{
153	  \fontsize{19}{27}\selectfont
154	  {\fontsize{17}{22}\selectfont\color{textmuted}\textit{%
155	    Education was once a privilege for the elite.
156	    It is now a near-universal right.}}
157	
158	  \vspace{8pt}
159	  \noindent\begin{tikzpicture}
160	    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 0.9) {1800};
161	    \fill[divider] (1.3cm, 0.64cm) rectangle (7.2cm, 1.10cm);
162	    \fill[accent!80] (1.3cm, 0.64cm) rectangle (2.48cm, 1.10cm);
163	    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{accent}] at (7.32cm, 0.87cm) {$<$20\%};
164	    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 0.05) {2024};
165	    \fill[divider] (1.3cm, -0.18cm) rectangle (7.2cm, 0.28cm);
166	    \fill[successgreen!85] (1.3cm, -0.18cm) rectangle (7.08cm, 0.28cm);
167	    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{successgreen}] at (7.32cm, 0.05cm) {$>$80\%};
168	    \node[anchor=west, font=\fontsize{13}{17}\selectfont\color{textmuted}] at (1.3cm, -0.5cm) {Share of adults with formal education};
169	  \end{tikzpicture}
170	
171	  \vspace{8pt}
172	  \begin{itemize}
173	    \item Fewer than \textbf{\color{accent}1 in 5} adults educated in 1800
174	    \item More than \textbf{\color{successgreen}4 in 5} adults educated today
175	    \item Literacy rates have followed the same trajectory
176	    \item 200 years: elite privilege $\to$ near-universal access
177	  \end{itemize}
178	
179	  \vspace{6pt}
180	  \noindent\colorbox{accent!22!bgcard}{\parbox{0.92\linewidth}{%
181	    \fontsize{17}{22}\selectfont\color{textlight}
182	    \textbf{\color{accentgold} The single greatest expansion} of human
183	    opportunity in recorded history --- but the story is not over.
184	  }}
185	}
186	
187	\posterbox[crisiscard, title={244 Million Children Still Out of School}
188	]{name=outofschool, column=1, between=row10 and row16}{
189	  \fontsize{19}{27}\selectfont
190	
191	  \begin{center}
192	    {\fontsize{90}{100}\selectfont\bfseries\color{warnred} 244}\\[2pt]
193	    {\fontsize{21}{27}\selectfont\bfseries\color{textmuted} million children not in school (2023)}
194	  \end{center}
195	
196	  \vspace{6pt}
197	  \noindent\colorbox{warnred!18!bgcard}{\parbox{0.92\linewidth}{%
198	    \fontsize{17}{23}\selectfont
199	    \begin{tabular}{@{}lll@{}}
200	      \textbf{\color{warnred} $\sim$60M} & {\color{textmuted} primary-school age} & {\color{textmuted}(6--11 yrs)}\\[4pt]
201	      \textbf{\color{warnred} $\sim$184M} & {\color{textmuted} secondary-school age} & {\color{textmuted}(12--17 yrs)}\\
202	    \end{tabular}
203	  }}
204	
205	  \vspace{8pt}
206	  \begin{itemize}
207	    \item \textbf{Secondary dropout is the dominant driver}
208	    \item Many finish primary --- but never continue
209	    \item Concentrated in Sub-Saharan Africa \& South Asia
210	    \item Conflict, poverty, and distance are key barriers
211	  \end{itemize}
212	
213	  \vspace{6pt}
214	  \noindent\colorbox{warnred!20!bgcard}{\parbox{0.92\linewidth}{%
215	    \fontsize{17}{22}\selectfont\color{textlight}\centering
216	    \textbf{Larger than the entire population of Brazil.}
217	  }}
218	}
219	
220	\posterbox[coralcard, title={Closing the Gender Gap}
221	]{name=gender, column=1, between=row16 and bottom}{
222	  \fontsize{18}{25}\selectfont
223	  {\fontsize{16}{21}\selectfont\color{textmuted}\textit{%
224	    Historically, boys were far more likely to attend school.}}
225	
226	  \vspace{8pt}
227	  \renewcommand{\arraystretch}{1.5}
228	  \begin{tabular}{@{}p{3.2cm}p{5.6cm}@{}}
229	    \rowcolor{bgcard}
230	    {\fontsize{15}{19}\selectfont\color{textmuted}\textbf{Level}} &
231	    {\fontsize{15}{19}\selectfont\color{textmuted}\textbf{Gender Gap (2023)}} \\
232	    \rowcolor{bglightcard}
233	    {\fontsize{16}{21}\selectfont Primary} &
234	    {\fontsize{16}{21}\selectfont\color{successgreen} Nearly closed globally} \\
235	    \rowcolor{bgcard}
236	    {\fontsize{16}{21}\selectfont Secondary} &
237	    {\fontsize{16}{21}\selectfont\color{successgreen} Nearly closed globally} \\
238	    \rowcolor{bglightcard}
239	    {\fontsize{16}{21}\selectfont Tertiary} &
240	    {\fontsize{16}{21}\selectfont\color{accentgold} Women now exceed men} \\
241	  \end{tabular}
242	
243	  \vspace{6pt}
244	  \noindent\colorbox{warnred!18!bgcard}{\parbox{0.92\linewidth}{%
245	    \fontsize{16}{21}\selectfont
246	    \textbf{\color{warnred} Exception:} In Afghanistan and parts of the
247	    Sahel, girls remain severely excluded at all levels.
248	  }}
249	}
