254	
255	\posterbox[crisiscard, title={The Learning Crisis: Enrollment $\neq$ Learning}
256	]{name=crisis, column=2, between=row4 and row11}{
257	  \fontsize{19}{27}\selectfont
258	  {\fontsize{17}{22}\selectfont\color{textmuted}\textit{%
259	    Being in school is not the same as learning. Millions attend
260	    without gaining basic skills.}}
261	
262	  \vspace{8pt}
263	  \begin{center}
264	    \begin{tikzpicture}
265	      % Donut chart: only 20% proficient
266	      \fill[divider] (0,0) circle (2.4cm);
267	      \fill[successgreen!75] (0,0) -- (2.4cm, 0) arc(0:72:2.4cm) -- cycle;
268	      \fill[bgcard] (0,0) circle (1.38cm);
269	      \node[font=\fontsize{28}{34}\selectfont\bfseries, text=warnred] at (0,0.14) {$<$20\%};
270	      \node[font=\fontsize{12}{15}\selectfont, text=textmuted] at (0,-0.36) {proficient};
271	      \node[font=\fontsize{13}{16}\selectfont, text=textmuted, anchor=west] at (2.55cm, 0.75cm) {Reach minimum};
272	      \node[font=\fontsize{13}{16}\selectfont, text=textmuted, anchor=west] at (2.55cm, 0.37cm) {reading proficiency};
273	      \node[font=\fontsize{13}{16}\selectfont, text=successgreen, anchor=west] at (2.55cm,-0.08cm) {(low-income)};
274	      \node[font=\fontsize{13}{16}\selectfont, text=textmuted, anchor=west] at (2.55cm,-0.45cm) {by end of primary};
275	      \node[font=\fontsize{13}{16}\selectfont, text=warnred!80, anchor=east] at (-2.55cm, -0.5cm) {80\%+ enrolled};
276	      \node[font=\fontsize{13}{16}\selectfont, text=warnred!80, anchor=east] at (-2.55cm, -0.88cm) {but not learning};
277	    \end{tikzpicture}
278	  \end{center}
279	
280	  \vspace{6pt}
281	  \begin{itemize}
282	    \item Enrollment $\neq$ proficiency: the gap is stark
283	    \item Most cannot \textbf{identify key ideas} in a text
284	    \item Invisible crisis: hidden behind enrollment data
285	    \item Problem concentrated in \textbf{lower-income countries}
286	  \end{itemize}
287	}
288	
