%% ══════════════════════════════════════════════════════

\posterbox[crisiscard, title={The Learning Crisis: Enrollment $\neq$ Learning}
]{name=crisis, column=2, between=row4 and row11}{
  \fontsize{19}{27}\selectfont
  {\fontsize{17}{22}\selectfont\color{textmuted}\textit{%
    Being in school is not the same as learning. Millions attend
    without gaining basic skills.}}

  \vspace{8pt}
  \begin{center}
    \begin{tikzpicture}
      % Donut chart: only 20% proficient
      \fill[divider] (0,0) circle (2.4cm);
      \fill[successgreen!75] (0,0) -- (2.4cm, 0) arc(0:72:2.4cm) -- cycle;
      \fill[bgcard] (0,0) circle (1.38cm);
      \node[font=\fontsize{28}{34}\selectfont\bfseries, text=warnred] at (0,0.14) {$<$20\%};
      \node[font=\fontsize{12}{15}\selectfont, text=textmuted] at (0,-0.36) {proficient};
      \node[font=\fontsize{13}{16}\selectfont, text=textmuted, anchor=west] at (2.55cm, 0.75cm) {Reach minimum};
      \node[font=\fontsize{13}{16}\selectfont, text=textmuted, anchor=west] at (2.55cm, 0.37cm) {reading proficiency};
      \node[font=\fontsize{13}{16}\selectfont, text=successgreen, anchor=west] at (2.55cm,-0.08cm) {(low-income)};
      \node[font=\fontsize{13}{16}\selectfont, text=textmuted, anchor=west] at (2.55cm,-0.45cm) {by end of primary};
      \node[font=\fontsize{13}{16}\selectfont, text=warnred!80, anchor=east] at (-2.55cm, -0.5cm) {80\%+ enrolled};
      \node[font=\fontsize{13}{16}\selectfont, text=warnred!80, anchor=east] at (-2.55cm, -0.88cm) {but not learning};
    \end{tikzpicture}
  \end{center}

  \vspace{6pt}
  \begin{itemize}
    \item Enrollment $\neq$ proficiency: the gap is stark
    \item Most cannot \textbf{identify key ideas} in a text
    \item Invisible crisis: hidden behind enrollment data
    \item Problem concentrated in \textbf{lower-income countries}
  \end{itemize}
}

\posterbox[coralcard, title={A World Divided: Quality Schooling}
]{name=quality, column=2, between=row11 and row17}{
  \fontsize{19}{27}\selectfont
  {\fontsize{17}{22}\selectfont\color{textmuted}\textit{%
    Same years enrolled, vastly different years \textbf{actually learned.}}}

  \vspace{8pt}
  \begin{tikzpicture}
    \node[anchor=west, font=\fontsize{14}{18}\selectfont\color{textmuted}]
      at (0, 4.1) {Learning-Adjusted Years of Schooling};

    % Bar 1: Poorest <3 years
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\color{textmuted}]
      at (0, 3.45) {Poorest countries};
    \fill[divider] (4.4cm, 3.15cm) rectangle (10.6cm, 3.70cm);
    \fill[warnred] (4.4cm, 3.15cm) rectangle (6.09cm, 3.70cm);
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{warnred}]
      at (10.75cm, 3.42cm) {$<$3 yrs};

    % Bar 2: SSA/SA <7 years
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\color{textmuted}]
      at (0, 2.52) {South Asia / Sub-Saharan Africa};
    \fill[divider] (4.4cm, 2.22cm) rectangle (10.6cm, 2.77cm);
    \fill[accentgold!75] (4.4cm, 2.22cm) rectangle (8.32cm, 2.77cm);
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{accentgold}]
      at (10.75cm, 2.49cm) {$<$7 yrs};

    % Bar 3: High-income 10+
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\color{textmuted}]
      at (0, 1.58) {High-income countries};
    \fill[divider] (4.4cm, 1.28cm) rectangle (10.6cm, 1.83cm);
    \fill[successgreen!80] (4.4cm, 1.28cm) rectangle (10.4cm, 1.83cm);
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{successgreen}]
      at (10.75cm, 1.55cm) {10+ yrs};

    % Scale ticks
    \foreach \x/\lab in {4.4/0, 6.09/3, 7.79/7, 10.4/10} {
      \draw[textmuted, opacity=0.4] (\x cm, 0.90cm) -- (\x cm, 1.05cm);
      \node[font=\fontsize{11}{14}\selectfont\color{textmuted}, opacity=0.7]
        at (\x cm, 0.65cm) {\lab};
    }
    \node[font=\fontsize{12}{15}\selectfont\color{textmuted}]
      at (7.5cm, 0.30cm) {Years};
  \end{tikzpicture}

  \vspace{6pt}
