\posterbox[navycard, title={Two Centuries of Educational Expansion}
]{name=history, column=1, between=row4 and row10}{
  \fontsize{19}{27}\selectfont
  {\fontsize{17}{22}\selectfont\color{textmuted}\textit{%
    Education was once a privilege for the elite.
    It is now a near-universal right.}}

  \vspace{8pt}
  \noindent\begin{tikzpicture}
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 0.9) {1800};
    \fill[divider] (1.3cm, 0.64cm) rectangle (7.2cm, 1.10cm);
    \fill[accent!80] (1.3cm, 0.64cm) rectangle (2.48cm, 1.10cm);
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{accent}] at (7.32cm, 0.87cm) {$<$20\%};
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}] at (0, 0.05) {2024};
    \fill[divider] (1.3cm, -0.18cm) rectangle (7.2cm, 0.28cm);
    \fill[successgreen!85] (1.3cm, -0.18cm) rectangle (7.08cm, 0.28cm);
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\bfseries\color{successgreen}] at (7.32cm, 0.05cm) {$>$80\%};
    \node[anchor=west, font=\fontsize{13}{17}\selectfont\color{textmuted}] at (1.3cm, -0.5cm) {Share of adults with formal education};
  \end{tikzpicture}

  \vspace{8pt}
  \begin{itemize}
    \item Fewer than \textbf{\color{accent}1 in 5} adults educated in 1800
    \item More than \textbf{\color{successgreen}4 in 5} adults educated today
    \item Literacy rates have followed the same trajectory
    \item 200 years: elite privilege $\to$ near-universal access
  \end{itemize}

  \vspace{6pt}
  \noindent\colorbox{accent!22!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{22}\selectfont\color{textlight}
    \textbf{\color{accentgold} The single greatest expansion} of human
    opportunity in recorded history --- but the story is not over.
  }}
}

