\posterbox[crisiscard, title={The Learning Crisis: Enrollment $\neq$ Learning}
]{name=crisis, column=2, between=row3 and row9}{
  \fontsize{21}{29}\selectfont
  {\fontsize{20}{27}\selectfont\color{textmuted}\textit{%
    Being in school is not the same as learning. Millions attend
    without gaining basic skills.}}

  \vspace{8pt}
  \begin{center}
    \begin{tikzpicture}
      \fill[divider] (0,0) circle (3.0cm);
      \fill[successgreen!75] (0,0) -- (3.0cm, 0) arc(0:72:3.0cm) -- cycle;
      \fill[bgcard] (0,0) circle (1.72cm);
      \node[font=\fontsize{30}{36}\selectfont\bfseries, text=warnred] at (0,0.18) {$<$20\%};
      \node[font=\fontsize{14}{17}\selectfont, text=textmuted] at (0,-0.44) {proficient};
      \node[font=\fontsize{15}{19}\selectfont, text=textmuted, anchor=west] at (3.15cm, 0.88cm) {Reach minimum};
      \node[font=\fontsize{15}{19}\selectfont, text=textmuted, anchor=west] at (3.15cm, 0.44cm) {reading proficiency};
      \node[font=\fontsize{15}{19}\selectfont, text=successgreen, anchor=west] at (3.15cm,-0.06cm) {(low-income)};
      \node[font=\fontsize{15}{19}\selectfont, text=textmuted, anchor=west] at (3.15cm,-0.50cm) {by end of primary};
      \node[font=\fontsize{15}{19}\selectfont, text=warnred!80, anchor=east] at (-3.15cm, -0.50cm) {80\%+ enrolled};
      \node[font=\fontsize{15}{19}\selectfont, text=warnred!80, anchor=east] at (-3.15cm, -0.94cm) {but not learning};
    \end{tikzpicture}
  \end{center}

  \vspace{6pt}
  \begin{itemize}
    \item Enrollment $\neq$ proficiency: the gap is stark
    \item Most cannot \textbf{identify key ideas} in a text
    \item Cannot link reading to their own experience
    \item Invisible crisis: hidden behind enrollment data
    \item Problem concentrated in \textbf{lower-income countries}
  \end{itemize}

  \vspace{6pt}
  \noindent\colorbox{warnred!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{23}\selectfont\color{textmuted}
    \textbf{\color{warnred} Root causes:} large class sizes, under-trained teachers,
    absenteeism, instruction in a language children don't speak at home.
  }}
}

\posterbox[coralcard, title={A World Divided: Quality Schooling}
]{name=quality, column=2, between=row9 and row14}{
  \fontsize{21}{29}\selectfont
  {\fontsize{20}{27}\selectfont\color{textmuted}\textit{%
    Same years enrolled, vastly different years \textbf{actually learned.}}}

  \vspace{10pt}
  \begin{tikzpicture}
    \node[anchor=west, font=\fontsize{16}{20}\selectfont\color{textmuted}]
      at (0, 4.5) {Learning-Adjusted Years of Schooling};

    \node[anchor=west, font=\fontsize{18}{23}\selectfont\color{textmuted}]
      at (0, 3.78) {Poorest countries};
    \fill[divider] (5.0cm, 3.46cm) rectangle (11.8cm, 4.04cm);
    \fill[warnred] (5.0cm, 3.46cm) rectangle (6.86cm, 4.04cm);
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\bfseries\color{warnred}]
      at (11.95cm, 3.75cm) {$<$3 yrs};

    \node[anchor=west, font=\fontsize{18}{23}\selectfont\color{textmuted}]
      at (0, 2.76) {South Asia / Sub-Saharan Africa};
    \fill[divider] (5.0cm, 2.44cm) rectangle (11.8cm, 3.02cm);
    \fill[accentgold!75] (5.0cm, 2.44cm) rectangle (9.34cm, 3.02cm);
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\bfseries\color{accentgold}]
      at (11.95cm, 2.73cm) {$<$7 yrs};

    \node[anchor=west, font=\fontsize{18}{23}\selectfont\color{textmuted}]
      at (0, 1.74) {High-income countries};
    \fill[divider] (5.0cm, 1.42cm) rectangle (11.8cm, 2.00cm);
    \fill[successgreen!80] (5.0cm, 1.42cm) rectangle (11.6cm, 2.00cm);
    \node[anchor=west, font=\fontsize{17}{22}\selectfont\bfseries\color{successgreen}]
      at (11.95cm, 1.71cm) {10+ yrs};

    \foreach \x/\lab in {5.0/0, 6.86/3, 8.72/7, 11.6/10} {
      \draw[textmuted, opacity=0.4] (\x cm, 1.00cm) -- (\x cm, 1.18cm);
      \node[font=\fontsize{13}{16}\selectfont\color{textmuted}, opacity=0.7]
        at (\x cm, 0.72cm) {\lab};
    }
    \node[font=\fontsize{14}{17}\selectfont\color{textmuted}]
      at (8.3cm, 0.35cm) {Years};
  \end{tikzpicture}

  \vspace{8pt}
  \begin{itemize}
    \item Children in poorest nations get \textbf{less than $\frac{1}{3}$} the quality schooling of wealthy peers
    \item Most of the world's children live where averages fall \textbf{below 7 years}
    \item Gap reflects teacher quality, resources, and infrastructure
    \item The gap compounds: poor schooling $\to$ lower productivity $\to$ poverty
  \end{itemize}

  \vspace{6pt}
  \noindent\colorbox{accentgold!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{18}{24}\selectfont\centering
    A child born poor faces a \textbf{\color{warnred} 3$\times$ disadvantage}
    in quality education before turning 15.
  }}
}

\posterbox[takeawaycard, title={Key Takeaway}
]{name=takeaway, column=2, between=row14 and bottom}{
  \fontsize{21}{29}\selectfont

  \begin{itemize}[label={\color{white}$\star$}, itemsep=8pt]
    \item Remarkable progress over 200 years --- but \textbf{hundreds of millions} left behind
    \item 244 million children out of school; many more \textbf{learning too little}
    \item \textbf{Closing the learning gap} --- not just enrollment --- is the defining challenge
    \item \textbf{Geography and income} still determine a child's educational fate
    \item Gender gaps have closed globally --- \textbf{but not everywhere}
  \end{itemize}

  \vspace{10pt}
  \noindent\colorbox{primary!60!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{18}{25}\selectfont\color{textlight}\centering
    \textit{``The job is not done until every child has access to
    \textbf{quality} education --- not just a seat in a classroom.''}
  }}

  \vspace{10pt}
  \noindent\colorbox{accent!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{16}{22}\selectfont\color{textmuted}\centering
    Data sources: UNESCO Institute for Statistics, World Bank Human Capital Index,
    Our World in Data (2020--2023)
  }}
}

