\documentclass{article}
% A1 portrait: 594mm x 841mm
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{microtype}
\usepackage{tikz}
\pagestyle{empty}

% ── Color Theme: Deep Navy + Amber/Coral (public exhibition) ──
\definecolor{primary}{HTML}{0D1B35}      % deep navy
\definecolor{secondary}{HTML}{1A3A6B}    % medium navy
\definecolor{accent}{HTML}{E86A2B}       % warm coral/amber
\definecolor{accentgold}{HTML}{F5A623}   % bright amber
\definecolor{bgposter}{HTML}{0A1526}     % very dark navy bg
\definecolor{bgcard}{HTML}{142035}       % card bg (slightly lighter)
\definecolor{bglightcard}{HTML}{1C2E50}  % lighter card
\definecolor{bgstatcard}{HTML}{1A3060}   % stat callout bg
\definecolor{textlight}{HTML}{E8EDF5}    % main text on dark
\definecolor{textmuted}{HTML}{9DAFC8}    % muted text
\definecolor{textheader}{HTML}{FFFFFF}   % section header
\definecolor{successgreen}{HTML}{27AE60} % green for positive stats
\definecolor{warnred}{HTML}{E74C3C}      % red for crisis stats
\definecolor{divider}{HTML}{2A4A7F}      % subtle divider

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=18pt, itemsep=5pt, parsep=0pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}

% ── Card styles ──
\tcbset{
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=bgcard,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=10pt, bottom=10pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=secondary,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
  coralcard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=bglightcard,
    borderline west={5pt}{0pt}{accentgold},
    left=14pt, right=12pt, top=10pt, bottom=10pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=bgcard,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
  crisiscard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=bgcard,
    borderline west={5pt}{0pt}{warnred},
    left=14pt, right=12pt, top=10pt, bottom=10pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=warnred!60!bgcard,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
  takeawaycard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=accent!20!bgcard,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=10pt, bottom=10pt,
    fonttitle=\fontsize{28}{34}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=accent,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=0pt,
    valign=top,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

%% Full-page background (renders first, behind everything)
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=bgposter, colframe=bgposter,
  top=0pt, bottom=0pt, left=0pt, right=0pt,
]{name=fullbg, column=1, span=2, between=top and bottom}{}

%% ══════════════════════════════════════════════════════
%% COMBINED TITLE + STAT HEADER (one box, no gap)
%% ══════════════════════════════════════════════════════
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=bgposter, colframe=bgposter,
  left=0pt, right=0pt, top=0pt, bottom=0pt,
]{name=header, column=1, span=2, between=top and row3}{
  % ── Title section ──
  \begin{tcolorbox}[
    enhanced, arc=0pt, boxrule=0pt,
    colback=primary, colframe=primary,
    left=30pt, right=30pt, top=14pt, bottom=10pt,
    halign=center,
    borderline south={3pt}{0pt}{accent},
  ]
    {\fontsize{54}{64}\selectfont\bfseries\color{white}%
      The\kern0.28em State\kern0.28em of\kern0.28em Global\kern0.28em Education}\\[6pt]
    {\fontsize{28}{36}\selectfont\color{textmuted}%
      Progress,\kern0.22em Gaps,\kern0.22em and\kern0.22em Inequality}\\[5pt]
    {\fontsize{18}{24}\selectfont\color{accent}%
      A data-driven look at two centuries of transformation --- and the work still ahead}
  \end{tcolorbox}%
  % ── Stat banner section ──
  \begin{tcolorbox}[
    enhanced, arc=0pt, boxrule=0pt,
    colback=bgstatcard, colframe=bgstatcard,
    left=8pt, right=8pt, top=10pt, bottom=10pt,
    halign=center,
    borderline south={2pt}{0pt}{divider},
  ]
    \centering
    \begin{minipage}[c]{0.22\linewidth}
      \centering
      {\fontsize{46}{54}\selectfont\bfseries\color{successgreen} $>$4 in 5}\\[4pt]
      {\fontsize{17}{22}\selectfont\color{textmuted} Adults with formal\\education today}
    \end{minipage}\hfill
    \textcolor{divider}{\rule{1.5pt}{34mm}}\hfill
    \begin{minipage}[c]{0.22\linewidth}
      \centering
      {\fontsize{46}{54}\selectfont\bfseries\color{warnred} 244M}\\[4pt]
      {\fontsize{17}{22}\selectfont\color{textmuted} Children out of\\school (2023)}
    \end{minipage}\hfill
    \textcolor{divider}{\rule{1.5pt}{34mm}}\hfill
    \begin{minipage}[c]{0.22\linewidth}
      \centering
      {\fontsize{46}{54}\selectfont\bfseries\color{warnred} $<$20\%}\\[4pt]
      {\fontsize{17}{22}\selectfont\color{textmuted} Reading proficiency\\(low-income countries)}
    \end{minipage}\hfill
    \textcolor{divider}{\rule{1.5pt}{34mm}}\hfill
    \begin{minipage}[c]{0.22\linewidth}
      \centering
      {\fontsize{46}{54}\selectfont\bfseries\color{accentgold} 3$\times$}\\[4pt]
      {\fontsize{17}{22}\selectfont\color{textmuted} Quality schooling gap:\\poorest vs.\ richest}
    \end{minipage}
  \end{tcolorbox}%
}

%% ══════════════════════════════════════════════════════
%% LEFT COLUMN
%% ══════════════════════════════════════════════════════

\posterbox[navycard, title={Two Centuries of Educational Expansion}
]{name=history, column=1, between=row3 and row8}{
  \fontsize{21}{29}\selectfont
  {\fontsize{20}{27}\selectfont\color{textmuted}\textit{%
    Education was once a privilege for the elite.
    It is now a near-universal right.}}

  \vspace{10pt}
  \noindent\begin{tikzpicture}
    \node[anchor=west, font=\fontsize{19}{24}\selectfont\color{textmuted}] at (0, 0.95) {1800};
    \fill[divider] (1.5cm, 0.66cm) rectangle (8.0cm, 1.18cm);
    \fill[accent!80] (1.5cm, 0.66cm) rectangle (2.80cm, 1.18cm);
    \node[anchor=west, font=\fontsize{18}{23}\selectfont\bfseries\color{accent}] at (8.15cm, 0.92cm) {$<$20\%};
    \node[anchor=west, font=\fontsize{19}{24}\selectfont\color{textmuted}] at (0, 0.06) {2024};
    \fill[divider] (1.5cm, -0.22cm) rectangle (8.0cm, 0.30cm);
    \fill[successgreen!85] (1.5cm, -0.22cm) rectangle (7.85cm, 0.30cm);
    \node[anchor=west, font=\fontsize{18}{23}\selectfont\bfseries\color{successgreen}] at (8.15cm, 0.04cm) {$>$80\%};
    \node[anchor=west, font=\fontsize{15}{19}\selectfont\color{textmuted}] at (1.5cm, -0.58cm) {Share of adults with formal education};
  \end{tikzpicture}

  \vspace{10pt}
  \begin{itemize}
    \item Fewer than \textbf{\color{accent}1 in 5} adults educated in 1800
    \item More than \textbf{\color{successgreen}4 in 5} adults educated today
    \item Literacy rates followed the same trajectory
    \item 200 years: elite privilege $\to$ near-universal access
    \item World population educated rose from $\sim$200M to $\sim$5B+
  \end{itemize}

  \vspace{8pt}
  \noindent\colorbox{accent!22!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{19}{25}\selectfont\color{textlight}
    \textbf{\color{accentgold} The single greatest expansion} of human
    opportunity in recorded history --- but the story is not over.
  }}

  \vspace{8pt}
  \noindent\colorbox{divider!60!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{23}\selectfont\color{textmuted}
    \textbf{\color{textlight} Key driver:} Mass public schooling systems, rising incomes, and
    international development commitments turned education from a luxury into infrastructure.
  }}
}

\posterbox[crisiscard, title={244 Million Children Still Out of School}
]{name=outofschool, column=1, between=row8 and row13}{
  \fontsize{21}{29}\selectfont

  \begin{center}
    {\fontsize{96}{106}\selectfont\bfseries\color{warnred} 244}\\[2pt]
    {\fontsize{21}{27}\selectfont\bfseries\color{textmuted} million children not in school (2023)}
  \end{center}

  \vspace{4pt}
  \noindent\colorbox{warnred!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{19}{26}\selectfont
    \begin{tabular}{@{}lll@{}}
      \textbf{\color{warnred} $\sim$60M} & {\color{textmuted} primary-school age} & {\color{textmuted}(6--11 yrs)}\\[6pt]
      \textbf{\color{warnred} $\sim$184M} & {\color{textmuted} secondary-school age} & {\color{textmuted}(12--17 yrs)}\\
    \end{tabular}
  }}

  \vspace{8pt}
  \begin{itemize}
    \item \textbf{Secondary dropout is the dominant driver}
    \item Many finish primary --- but never continue
    \item Concentrated in Sub-Saharan Africa \& South Asia
    \item Conflict, poverty, and distance are key barriers
    \item Girls disproportionately affected in fragile states
  \end{itemize}

  \vspace{8pt}
  \noindent\colorbox{warnred!20!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{19}{25}\selectfont\color{textlight}\centering
    \textbf{Larger than the entire population of Brazil.}
  }}
}

\posterbox[coralcard, title={Closing the Gender Gap}
]{name=gender, column=1, between=row13 and bottom}{
  \fontsize{21}{29}\selectfont
  {\fontsize{20}{27}\selectfont\color{textmuted}\textit{%
    Historically, boys were far more likely to attend school.
    Today, that gap has largely closed.}}

  \vspace{10pt}
  \renewcommand{\arraystretch}{1.65}
  \begin{tabular}{@{}p{3.4cm}p{6.2cm}@{}}
    \rowcolor{bgcard}
    {\fontsize{17}{22}\selectfont\color{textmuted}\textbf{Level}} &
    {\fontsize{17}{22}\selectfont\color{textmuted}\textbf{Gender Gap (2023)}} \\
    \rowcolor{bglightcard}
    {\fontsize{19}{25}\selectfont Primary} &
    {\fontsize{19}{25}\selectfont\color{successgreen} Nearly closed globally} \\
    \rowcolor{bgcard}
    {\fontsize{19}{25}\selectfont Secondary} &
    {\fontsize{19}{25}\selectfont\color{successgreen} Nearly closed globally} \\
    \rowcolor{bglightcard}
    {\fontsize{19}{25}\selectfont Tertiary} &
    {\fontsize{19}{25}\selectfont\color{accentgold} Women now exceed men} \\
  \end{tabular}

  \vspace{10pt}
  \begin{itemize}
    \item In 1970, boys outnumbered girls in school by a wide margin
    \item By 2000, primary enrollment parity largely achieved globally
    \item Women now earn more university degrees than men in most regions
    \item Progress driven by legal reforms, girls' education campaigns
  \end{itemize}

  \vspace{8pt}
  \noindent\colorbox{warnred!18!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{18}{24}\selectfont
    \textbf{\color{warnred} Exception:} In Afghanistan and parts of the
    Sahel, girls remain severely excluded at all levels. Afghanistan
    banned girls from secondary school and university in 2022.
  }}

  \vspace{8pt}
  \noindent\colorbox{accentgold!15!bgcard}{\parbox{0.92\linewidth}{%
    \fontsize{17}{23}\selectfont\color{textmuted}
    \textbf{\color{accentgold} Why it matters:} Each additional year of girls'
    schooling raises future earnings by 8--10\% and reduces child mortality.
  }}
}

%% ══════════════════════════════════════════════════════
%% RIGHT COLUMN
%% ══════════════════════════════════════════════════════

\posterbox[crisiscard, title={The Learning Crisis: Enrollment $\neq$ Learning}
]{name=crisis, column=2, between=row3 and row9}{
  \fontsize{21}{29}\selectfont
  {\fontsize{20}{27}\selectfont\color{textmuted}\textit{%
    Being in school is not the same as learning. Millions attend
    without gaining basic skills.}}

  \vspace{8pt}
  \begin{center}
    \begin{tikzpicture}
      \fill[divider] (0,0) circle (3.0cm);
      \fill[successgreen!75] (0,0) -- (3.0cm, 0) arc(0:72:3.0cm) -- cycle;
      \fill[bgcard] (0,0) circle (1.72cm);
      \node[font=\fontsize{30}{36}\selectfont\bfseries, text=warnred] at (0,0.18) {$<$20\%};
      \node[font=\fontsize{14}{17}\selectfont, text=textmuted] at (0,-0.44) {proficient};
      \node[font=\fontsize{15}{19}\selectfont, text=textmuted, anchor=west] at (3.15cm, 0.88cm) {Reach minimum};
      \node[font=\fontsize{15}{19}\selectfont, text=textmuted, anchor=west] at (3.15cm, 0.44cm) {reading proficiency};
      \node[font=\fontsize{15}{19}\selectfont, text=successgreen, anchor=west] at (3.15cm,-0.06cm) {(low-income)};
      \node[font=\fontsize{15}{19}\selectfont, text=textmuted, anchor=west] at (3.15cm,-0.50cm) {by end of primary};
      \node[font=\fontsize{15}{19}\selectfont, text=warnred!80, anchor=east] at (-3.15cm, -0.50cm) {80\%+ enrolled};
      \node[font=\fontsize{15}{19}\selectfont, text=warnred!80, anchor=east] at (-3.15cm, -0.94cm) {but not learning};
    \end{tikzpicture}
  \end{center}

  \vspace{6pt}
  \begin{itemize}
    \item Enrollment $\neq$ proficiency: the gap is stark
    \item Most cannot \textbf{identify key ideas} in a text
